('sweet-pea', 'Sweet pea', 'Lathyrus odoratus', 'annual', 'hardy', 'H5', 'easy', '{"autumnSow":true,"autumnSowWeeksBeforeFrost":3,"indoorWeeksBeforeFrost":8,"transplantWeeksAfterFrost":-2,"directSowWeeksAfterFrost":-4,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":12,"germTempMaxC":16,"germDaysMin":10,"germDaysMax":20,"daysFromSowToBloom":90,"bloomWeeksFromLastFrost":null,"successionWeeks":null,"defaultSuccessions":1,"pinch":"once","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":-4,"support":"trellis","supportDaysAfterPlant":0,"yearsToEstablish":1,"difficulty":"easy","caution":"Seeds are poisonous if eaten.","liftIfColderThanRhs":null,"heatSensitive":true,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":"Nick the coat or soak overnight. Sow deep — a long root run is the point of those long pots.","slug":"sweet-pea","commonName":"Sweet pea","latinName":"Lathyrus odoratus","lifeCycle":"annual","hardyClass":"hardy","usdaMin":3,"usdaMax":10,"rhs":"H5","climate":"cool","sowMethod":"either","daysFromPlantToBloom":70,"bloomWeeks":8,"spacingCm":15,"rowSpacingCm":20,"heightCm":180,"sun":"full","soil":"Rich soil and something to climb. Don''t let them dry out once they''re flowering.","harvestStage":"Cut when the bottom flower on the stem is just opening. Daily picking keeps them coming.","vaseLifeDaysMin":4,"vaseLifeDaysMax":6,"pestsDiseases":"Aphids, slugs on young plants, pollen beetles, and powdery mildew if they''re cramped.","overwintering":"An annual. Autumn-sown plants sit in pots through winter and flower earlier.","varieties":"Erewhon, Cupani, Charlie''s Angel, High Scent, Judith Wilkinson","notes":"The classic British autumn sow. October under cover in much of the UK; a bit earlier in Scotland, a bit later in the mild south-west.","colour":"#c45b86","roles":["focal","spike","spring"],"bloomSeasons":["spring","summer"]}'::jsonb),
('calendula', 'Calendula', 'Calendula officinalis', 'annual', 'hardy', 'H5', 'easy', '{"autumnSow":true,"autumnSowWeeksBeforeFrost":7,"indoorWeeksBeforeFrost":6,"transplantWeeksAfterFrost":-2,"directSowWeeksAfterFrost":-2,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":15,"germTempMaxC":20,"germDaysMin":5,"germDaysMax":14,"daysFromSowToBloom":60,"bloomWeeksFromLastFrost":null,"successionWeeks":3,"defaultSuccessions":3,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":1,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"calendula","commonName":"Calendula","latinName":"Calendula officinalis","lifeCycle":"annual","hardyClass":"hardy","usdaMin":2,"usdaMax":11,"rhs":"H5","climate":"cool","sowMethod":"either","daysFromPlantToBloom":45,"bloomWeeks":10,"spacingCm":25,"rowSpacingCm":25,"heightCm":60,"sun":"full","soil":"Any reasonable soil. They flower harder if you don''t overfeed.","harvestStage":"Cut when the petals are open but the centre is still tight.","vaseLifeDaysMin":6,"vaseLifeDaysMax":8,"pestsDiseases":"Aphids and powdery mildew. They''re otherwise hard to offend.","overwintering":"Hardy annual. Autumn seedlings overwinter and flower first.","varieties":"Sunset Buff, Indian Prince, Pink Surprise","notes":"Sow in September for the earliest flowers, then again in spring so you aren''t sick of them by June.","colour":"#e39b2b","roles":["focal","spring"],"bloomSeasons":["spring","summer","autumn"]}'::jsonb),
('cornflower', 'Cornflower', 'Centaurea cyanus', 'annual', 'hardy', 'H6', 'easy', '{"autumnSow":true,"autumnSowWeeksBeforeFrost":7,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":null,"directSowWeeksAfterFrost":-4,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":10,"germTempMaxC":16,"germDaysMin":7,"germDaysMax":14,"daysFromSowToBloom":70,"bloomWeeksFromLastFrost":null,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"netting","supportDaysAfterPlant":21,"yearsToEstablish":1,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"cornflower","commonName":"Cornflower","latinName":"Centaurea cyanus","lifeCycle":"annual","hardyClass":"hardy","usdaMin":2,"usdaMax":11,"rhs":"H6","climate":"cool","sowMethod":"direct","daysFromPlantToBloom":60,"bloomWeeks":6,"spacingCm":15,"rowSpacingCm":20,"heightCm":80,"sun":"full","soil":"Fertile, well-drained soil. They sulk in winter wet.","harvestStage":"Cut as the first petals show colour, before the flower is fully fluffy.","vaseLifeDaysMin":5,"vaseLifeDaysMax":7,"pestsDiseases":"Aphids. They flop if you skip the netting.","overwintering":"Hardy annual. Autumn sowns are the ones worth having.","varieties":"Classic Magic, Black Ball","notes":"Direct sow. They resent a move, and a spring-only sowing flowers later and floppier.","colour":"#3d5fbf","roles":["focal","spring"],"bloomSeasons":["spring","summer"]}'::jsonb),
('nigella', 'Nigella', 'Nigella damascena', 'annual', 'hardy', 'H6', 'easy', '{"autumnSow":true,"autumnSowWeeksBeforeFrost":7,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":null,"directSowWeeksAfterFrost":-6,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":12,"germTempMaxC":18,"germDaysMin":10,"germDaysMax":21,"daysFromSowToBloom":75,"bloomWeeksFromLastFrost":null,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":1,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"nigella","commonName":"Nigella","latinName":"Nigella damascena","lifeCycle":"annual","hardyClass":"hardy","usdaMin":2,"usdaMax":11,"rhs":"H6","climate":"cool","sowMethod":"direct","daysFromPlantToBloom":65,"bloomWeeks":5,"spacingCm":15,"rowSpacingCm":15,"heightCm":50,"sun":"full","soil":"Poorish, well-drained soil. Rich beds make leaves.","harvestStage":"Cut flowers as the colour shows, or leave a few for the seed pods.","vaseLifeDaysMin":6,"vaseLifeDaysMax":8,"pestsDiseases":"Few. They self-sow if you let the pods ripen.","overwintering":"Hardy annual. Leave some pods and they''ll return.","varieties":"Miss Jekyll, Delft Blue","notes":"Love-in-a-mist. Direct sow only — the taproot hates a tray. Pods are as useful as the flowers.","colour":"#7ea2d4","roles":["filler","spring"],"bloomSeasons":["spring","summer"]}'::jsonb),
('larkspur', 'Larkspur', 'Consolida ajacis', 'annual', 'hardy', 'H5', 'moderate', '{"autumnSow":true,"autumnSowWeeksBeforeFrost":8,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":null,"directSowWeeksAfterFrost":-6,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":10,"germTempMaxC":15,"germDaysMin":14,"germDaysMax":21,"daysFromSowToBloom":100,"bloomWeeksFromLastFrost":null,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"netting","supportDaysAfterPlant":28,"yearsToEstablish":1,"difficulty":"moderate","caution":"Poisonous if eaten.","liftIfColderThanRhs":null,"heatSensitive":true,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"larkspur","commonName":"Larkspur","latinName":"Consolida ajacis","lifeCycle":"annual","hardyClass":"hardy","usdaMin":2,"usdaMax":10,"rhs":"H5","climate":"cool","sowMethod":"direct","daysFromPlantToBloom":90,"bloomWeeks":5,"spacingCm":15,"rowSpacingCm":20,"heightCm":110,"sun":"full","soil":"Fertile, well-drained soil. They sulk in winter wet.","harvestStage":"Cut when a third of the florets on the spike are open.","vaseLifeDaysMin":6,"vaseLifeDaysMax":8,"pestsDiseases":"Crown rot in wet winters, powdery mildew. Slugs when young.","overwintering":"Autumn-sown rosettes sit through winter. In very wet ground, use a raised bed.","varieties":"Earl Grey, Misty, the forked types rather than hyacinth-flowered","notes":"Do not transplant if you can help it. A September sowing is the British way.","colour":"#9b7eb8","roles":["spike","spring"],"bloomSeasons":["spring","summer"]}'::jsonb),
