('orlaya', 'Orlaya', 'Orlaya grandiflora', 'annual', 'hardy', 'H5', 'easy', '{"autumnSow":true,"autumnSowWeeksBeforeFrost":6,"indoorWeeksBeforeFrost":6,"transplantWeeksAfterFrost":-1,"directSowWeeksAfterFrost":-2,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":12,"germTempMaxC":18,"germDaysMin":10,"germDaysMax":21,"daysFromSowToBloom":85,"bloomWeeksFromLastFrost":null,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":1,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"orlaya","commonName":"Orlaya","latinName":"Orlaya grandiflora","lifeCycle":"annual","hardyClass":"hardy","usdaMin":3,"usdaMax":10,"rhs":"H5","climate":"cool","sowMethod":"either","daysFromPlantToBloom":70,"bloomWeeks":6,"spacingCm":20,"rowSpacingCm":25,"heightCm":70,"sun":"full","soil":"Fertile, well-drained soil. They sulk in winter wet.","harvestStage":"Cut when the white lace is open but not browning.","vaseLifeDaysMin":5,"vaseLifeDaysMax":7,"pestsDiseases":"Slugs when small. Otherwise easy.","overwintering":"Hardy annual. Autumn sowing is kinder than a late spring one.","varieties":"The species","notes":"A finer white lace than ammi, and shorter. Lovely with sweet peas.","colour":"#f7f4ea","roles":["filler","spring"],"bloomSeasons":["spring","summer"]}'::jsonb),
