('geum', 'Geum', 'Geum', 'perennial', 'hardy', 'H7', 'easy', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":0,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":2,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":1,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"geum","commonName":"Geum","latinName":"Geum","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":4,"usdaMax":8,"rhs":"H7","climate":"cool","sowMethod":"division","daysFromPlantToBloom":60,"bloomWeeks":8,"spacingCm":30,"rowSpacingCm":30,"heightCm":50,"sun":"full","soil":"Moist but drained. They don''t enjoy a bake.","harvestStage":"Cut stems as the flowers open. Keep deadheading and they repeat.","vaseLifeDaysMin":5,"vaseLifeDaysMax":7,"pestsDiseases":"Slugs. Sawfly sometimes.","overwintering":"Hardy perennial. Divide when the clump gets woody.","varieties":"Totally Tangerine, Mrs J. Bradshaw","notes":"A long spring and early summer of wiry stems. Totally Tangerine earns its space.","colour":"#e07a3d","roles":["focal","spring"],"bloomSeasons":["spring","summer"]}'::jsonb),
('alchemilla', 'Lady''s mantle', 'Alchemilla mollis', 'perennial', 'hardy', 'H7', 'easy', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":-2,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":6,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":2,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"alchemilla","commonName":"Lady''s mantle","latinName":"Alchemilla mollis","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":3,"usdaMax":8,"rhs":"H7","climate":"mild","sowMethod":"division","daysFromPlantToBloom":70,"bloomWeeks":6,"spacingCm":40,"rowSpacingCm":40,"heightCm":45,"sun":"part","soil":"Almost any moist soil. It will seed into the paths.","harvestStage":"Cut the lime sprays as they foam out. Also useful as plain leaf.","vaseLifeDaysMin":7,"vaseLifeDaysMax":10,"pestsDiseases":"None worth naming. The seedlings are the issue.","overwintering":"Very hardy. Cut back after flowering if you don''t want a carpet.","varieties":"The species. A. erythropoda is smaller if the big one frightens you.","notes":"The filler that makes a bunch look expensive. It will also make a gravel path look botanical. Deadhead.","colour":"#d5de7a","roles":["filler","foliage"],"bloomSeasons":["spring","summer"]}'::jsonb),
('eryngium', 'Sea holly', 'Eryngium', 'perennial', 'hardy', 'H5', 'moderate', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":10,"transplantWeeksAfterFrost":0,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":18,"germTempMaxC":22,"germDaysMin":14,"germDaysMax":28,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":12,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":2,"difficulty":"moderate","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":false,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"eryngium","commonName":"Sea holly","latinName":"Eryngium","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":4,"usdaMax":9,"rhs":"H5","climate":"mild","sowMethod":"indoor","daysFromPlantToBloom":140,"bloomWeeks":6,"spacingCm":40,"rowSpacingCm":40,"heightCm":70,"sun":"full","soil":"Sharp drainage and sun. Winter wet kills more than frost.","harvestStage":"Cut when the thimble and the bracts are fully coloured. They dry without trying.","vaseLifeDaysMin":10,"vaseLifeDaysMax":14,"pestsDiseases":"Few. Slugs may try a young crown.","overwintering":"Hardy if the drainage is good. E. planum is tougher than some of the blue hybrids.","varieties":"Big Blue, E. planum, E. alpinum","notes":"A sun-lover. Seed is slow. Year two is when you get the stems you imagined.","colour":"#6a8fbf","roles":["focal","dried"],"bloomSeasons":["summer"]}'::jsonb),
('lupin', 'Lupin', 'Lupinus polyphyllus', 'perennial', 'hardy', 'H5', 'moderate', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":8,"transplantWeeksAfterFrost":-1,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":15,"germTempMaxC":20,"germDaysMin":7,"germDaysMax":21,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":6,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"stake","supportDaysAfterPlant":21,"yearsToEstablish":2,"difficulty":"moderate","caution":"Seeds are poisonous if eaten.","liftIfColderThanRhs":null,"heatSensitive":true,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":"Nick or soak the seed. Sear cut stems.","slug":"lupin","commonName":"Lupin","latinName":"Lupinus polyphyllus","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":4,"usdaMax":8,"rhs":"H5","climate":"cool","sowMethod":"indoor","daysFromPlantToBloom":100,"bloomWeeks":3,"spacingCm":40,"rowSpacingCm":45,"heightCm":90,"sun":"full","soil":"Well-drained, slightly acid is fine. They are legumes and don''t need a rich feed.","harvestStage":"Cut when the bottom flowers are open. Sear the stem or the vase life is a rumour.","vaseLifeDaysMin":4,"vaseLifeDaysMax":6,"pestsDiseases":"Aphids, spectacularly. Slugs on shoots.","overwintering":"Hardy. They dislike heat and they dislike being moved once the root is down.","varieties":"Gallery, Russell hybrids","notes":"A short vase life even when you do it right. Grow them because a spike of lupins is still a spike of lupins.","colour":"#7b6bb5","roles":["spike","spring"],"bloomSeasons":["spring","summer"]}'::jsonb),
('hydrangea', 'Hydrangea', 'Hydrangea paniculata', 'shrub', 'hardy', 'H6', 'moderate', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":0,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":14,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":3,"difficulty":"moderate","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":false,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"hydrangea","commonName":"Hydrangea","latinName":"Hydrangea paniculata","lifeCycle":"shrub","hardyClass":"hardy","usdaMin":3,"usdaMax":8,"rhs":"H6","climate":"mild","sowMethod":"division","daysFromPlantToBloom":120,"bloomWeeks":8,"spacingCm":120,"rowSpacingCm":150,"heightCm":180,"sun":"part","soil":"Moist, rich, and not a dry hedge bottom. Paniculata flowers on new wood, which is why it''s safer than a mophead after a late frost.","harvestStage":"Cut when the florets feel papery, not while they''re still soft and green-sappy. They drink deeply.","vaseLifeDaysMin":7,"vaseLifeDaysMax":12,"pestsDiseases":"Not many. Drought shows immediately as a sulk.","overwintering":"Hardy shrub. Prune paniculata in late winter or early spring. Mophead macrophylla flowers on old wood and loses buds to a late frost — grow it only if you can give it a sheltered wall.","varieties":"Limelight, Little Lime, Vanille Fraise. Macrophylla if you have a kind wall.","notes":"A shrub, not a seed packet. Plant it where it can stay. Cuts from year three are the realistic ones.","colour":"#e4efd4","roles":["focal","foliage","autumn"],"bloomSeasons":["summer","autumn"]}'::jsonb),
('chrysanthemum', 'Chrysanthemum', 'Chrysanthemum', 'perennial', 'half_hardy', 'H4', 'moderate', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":0,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":22,"successionWeeks":null,"defaultSuccessions":1,"pinch":"midseason","pinchDaysAfterPlant":21,"pinchWeeksFromLastFrost":null,"support":"netting","supportDaysAfterPlant":14,"yearsToEstablish":1,"difficulty":"moderate","caution":null,"liftIfColderThanRhs":"H4","heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":false,"hungry":true,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"chrysanthemum","commonName":"Chrysanthemum","latinName":"Chrysanthemum","lifeCycle":"perennial","hardyClass":"half_hardy","usdaMin":5,"usdaMax":9,"rhs":"H4","climate":"mild","sowMethod":"division","daysFromPlantToBloom":140,"bloomWeeks":6,"spacingCm":30,"rowSpacingCm":30,"heightCm":80,"sun":"full","soil":"Rich and well-drained. They are heavy feeders.","harvestStage":"Cut when the flower is open but the centre is still tight. Strip the lower leaves.","vaseLifeDaysMin":10,"vaseLifeDaysMax":14,"pestsDiseases":"Aphids, leaf miners, white rust. Buy clean stock.","overwintering":"Many garden mums need a winter mulch. Florist and heirloom stools are often lifted after flowering and kept barely moist, frost-free, then restarted from cuttings in spring.","varieties":"Avignon, Pip, Allouise, and other heirloom sprays rather than a tight pot-mum","notes":"The autumn flower. Pinch until midsummer, then stop, or you''ll still be pinching when you wanted flowers.","colour":"#d98a3a","roles":["focal","autumn"],"bloomSeasons":["autumn"]}'::jsonb),
('japanese-anemone', 'Japanese anemone', 'Eriocapella hupehensis', 'perennial', 'hardy', 'H6', 'easy', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":0,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":20,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":2,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"japanese-anemone","commonName":"Japanese anemone","latinName":"Eriocapella hupehensis","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":4,"usdaMax":8,"rhs":"H6","climate":"mild","sowMethod":"division","daysFromPlantToBloom":100,"bloomWeeks":8,"spacingCm":50,"rowSpacingCm":50,"heightCm":100,"sun":"part","soil":"Moist, reasonably fertile. They will wander once happy.","harvestStage":"Cut when a flower is open. Sear the stem if it wilts.","vaseLifeDaysMin":4,"vaseLifeDaysMax":6,"pestsDiseases":"Eelworm and leaf spot sometimes. The spread is the main feature and the main complaint.","overwintering":"Hardy. Slow to establish, then you will be offering divisions to neighbours.","varieties":"Honorine Jobert, Königin Charlotte","notes":"Autumn flowers for a spot that isn''t full baking sun. Give them two years before you judge them.","colour":"#f4efe8","roles":["focal","autumn"],"bloomSeasons":["autumn"]}'::jsonb),
('hellebore', 'Hellebore', 'Helleborus', 'perennial', 'hardy', 'H7', 'moderate', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":null,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":6,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":-8,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":3,"difficulty":"moderate","caution":"Poisonous if eaten, and the sap can irritate skin.","liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":false,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"hellebore","commonName":"Hellebore","latinName":"Helleborus","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":4,"usdaMax":9,"rhs":"H7","climate":"cool","sowMethod":"division","daysFromPlantToBloom":200,"bloomWeeks":8,"spacingCm":40,"rowSpacingCm":45,"heightCm":35,"sun":"shade","soil":"Humus-rich, drained, and out of the summer blast. Shade is a feature.","harvestStage":"Cut as flowers open and sear the stem. Or float a flower in a bowl, which is honest about the stem length.","vaseLifeDaysMin":5,"vaseLifeDaysMax":8,"pestsDiseases":"Black spot on leaves. Remove tired leaves in winter so the flowers show.","overwintering":"Very hardy. They want shade and patience, not a sunny annual bed.","varieties":"H. × hybridus, and H. foetidus if you want green bells","notes":"A winter and early spring cut. Plants are slow and not cheap. Buy one good plant rather than a packet of maybe.","colour":"#d7c4d4","roles":["focal","spring"],"bloomSeasons":["spring"]}'::jsonb),
('astilbe', 'Astilbe', 'Astilbe', 'perennial', 'hardy', 'H7', 'easy', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":0,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":8,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":2,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":false,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"astilbe","commonName":"Astilbe","latinName":"Astilbe","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":3,"usdaMax":8,"rhs":"H7","climate":"cool","sowMethod":"division","daysFromPlantToBloom":80,"bloomWeeks":4,"spacingCm":40,"rowSpacingCm":40,"heightCm":70,"sun":"shade","soil":"Moist. This is not a plant for a dry sunny bank. It will tell you, in brown.","harvestStage":"Cut when the plume is just fully fluffy. They drink, then they last if the water is clean.","vaseLifeDaysMin":5,"vaseLifeDaysMax":7,"pestsDiseases":"Few, apart from drought.","overwintering":"Very hardy. Leave the plumes for winter structure if you like, or cut them.","varieties":"Fanal, Bridal Veil, the chinensis types for slightly drier spots","notes":"A shade perennial for a damp corner. Useless vase material if you let it wilt once.","colour":"#e7b7c4","roles":["filler"],"bloomSeasons":["summer"]}'::jsonb),
('veronica', 'Veronica', 'Veronica longifolia', 'perennial', 'hardy', 'H7', 'easy', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":null,"transplantWeeksAfterFrost":0,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":null,"germTempMaxC":null,"germDaysMin":null,"germDaysMax":null,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":10,"successionWeeks":null,"defaultSuccessions":1,"pinch":"none","pinchDaysAfterPlant":null,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":2,"difficulty":"easy","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":true,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"veronica","commonName":"Veronica","latinName":"Veronica longifolia","lifeCycle":"perennial","hardyClass":"hardy","usdaMin":4,"usdaMax":8,"rhs":"H7","climate":"mild","sowMethod":"division","daysFromPlantToBloom":70,"bloomWeeks":6,"spacingCm":40,"rowSpacingCm":40,"heightCm":70,"sun":"full","soil":"Fertile and moist enough. They don''t want a bog or a desert.","harvestStage":"Cut when the spike is about half open.","vaseLifeDaysMin":6,"vaseLifeDaysMax":8,"pestsDiseases":"Powdery mildew if airless.","overwintering":"Hardy. Divide every few years.","varieties":"Blauriesin, Pink Eveline","notes":"A straightforward spike for early summer. Easy, which is allowed.","colour":"#4d6eb5","roles":["spike"],"bloomSeasons":["summer"]}'::jsonb),
('eucalyptus', 'Eucalyptus', 'Eucalyptus gunnii', 'shrub', 'half_hardy', 'H5', 'moderate', '{"autumnSow":false,"autumnSowWeeksBeforeFrost":null,"indoorWeeksBeforeFrost":8,"transplantWeeksAfterFrost":2,"directSowWeeksAfterFrost":null,"autumnPlantWeeksBeforeFrost":null,"germTempMinC":18,"germTempMaxC":22,"germDaysMin":14,"germDaysMax":28,"daysFromSowToBloom":null,"bloomWeeksFromLastFrost":null,"successionWeeks":null,"defaultSuccessions":1,"pinch":"once","pinchDaysAfterPlant":40,"pinchWeeksFromLastFrost":null,"support":"none","supportDaysAfterPlant":null,"yearsToEstablish":2,"difficulty":"moderate","caution":null,"liftIfColderThanRhs":null,"heatSensitive":false,"minSeasonDays":null,"needsWinterChill":false,"deadhead":false,"hungry":false,"biennialSummerSow":false,"presprout":false,"prep":null,"slug":"eucalyptus","commonName":"Eucalyptus","latinName":"Eucalyptus gunnii","lifeCycle":"shrub","hardyClass":"half_hardy","usdaMin":8,"usdaMax":11,"rhs":"H5","climate":"mild","sowMethod":"indoor","daysFromPlantToBloom":100,"bloomWeeks":20,"spacingCm":60,"rowSpacingCm":80,"heightCm":180,"sun":"full","soil":"Well-drained. Cider gum is the hardy one British growers actually get away with.","harvestStage":"Cut juvenile stems once the round leaves have sized up. Don''t strip the growing tip of a young plant bald in year one.","vaseLifeDaysMin":10,"vaseLifeDaysMax":14,"pestsDiseases":"Few outdoors. Cold wind in the first winter is the usual killer.","overwintering":"E. gunnii is about RHS H5. In colder gardens, treat it as annual foliage and expect short stems. Coppice established plants in spring for a flush of juvenile leaf.","varieties":"E. gunnii (cider gum). Baby blue (E. pulverulenta) is prettier and less hardy.","notes":"Grow cider gum if you want it to see a second year in much of the UK. Coppice it or it becomes a tree you need a ladder and a conversation about.","colour":"#8aa890","roles":["foliage"],"bloomSeasons":["summer","autumn"]}'::jsonb)
